python3 << 'EOF'
import re
import json

# Extract CSS properties from Webflow CSS
with open('/Users/yashbaldha/Desktop/Boldteq App/Marketing Site/Boldteq/boldteq-v1-0.webflow/css/boldteq-v1-0.webflow.css', 'r') as f:
    webflow_css = f.read()

# Find all classes and their complete properties
pattern = r'\.([a-zA-Z0-9_-]+)\s*\{([^}]+)\}'
matches = re.findall(pattern, webflow_css)

# Group by categories
beta_pricing_classes = {}
for class_name, properties in matches:
    if 'pricing' in class_name.lower() or 'button-pricing' in class_name:
        props_dict = {}
        for prop in properties.split(';'):
            if ':' in prop:
                key, val = prop.split(':', 1)
                props_dict[key.strip()] = val.strip()
        beta_pricing_classes[class_name] = props_dict

# Show specific classes
for cls in ['pricing-card', 'button-pricing', 'button-pricing.sky-prcing-button']:
    if cls in beta_pricing_classes:
        print(f"\n{cls}:")
        for prop, val in list(beta_pricing_classes[cls].items())[:5]:
            print(f"  {prop}: {val}")

# Count total
print(f"\n\nTotal pricing/button classes: {len(beta_pricing_classes)}")
print(f"Sample classes: {list(beta_pricing_classes.keys())[:10]}")
EOF

